{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In humans, [123/124/131I]AM281 readily permeates the BBB and enables CB1 receptor quantification, directly demonstrating meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In rats, ex vivo autoradiography after intravenous injection of [123I]AM281 shows good brain accumulation in CB1-rich regions, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A lower-similarity analog, compound 18a, showed little to no CNS penetration with a very low brain:plasma ratio, indicating that not all close analogs achieve CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The nearest and most direct evidence, from AM281 in humans and rats, demonstrates ready BBB permeation and brain accumulation. Although some lower-similarity analogs show poor CNS penetration, the strongest condition-matched evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct query-specific in vivo data are available; prediction relies on AM281 analogs with Morgan similarity around 0.4.",
    "Several structurally related compounds show poor brain penetration, so transferability to the query is not absolute."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

